use crate::value::Value;
use std::ptr;

pub static mut BYTES_ALLOCATED: usize = 0;

#[inline(always)]
pub fn track_alloc(n: usize) {
    unsafe { BYTES_ALLOCATED += n };
}
#[inline(always)]
pub fn track_free(n: usize) {
    unsafe { BYTES_ALLOCATED = BYTES_ALLOCATED.saturating_sub(n) };
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[repr(u8)]
pub enum ObjType {
    String,
    Function,
    Native,
    Closure,
    Upvalue,
    Class,
    Instance,
    BoundMethod,
}

#[repr(C)]
pub struct Obj {
    pub ty: ObjType,
    pub marked: bool,
    pub next: *mut Obj,
}

#[repr(C)]
pub struct ObjString {
    pub obj: Obj,
    pub hash: u32,
    pub chars: Box<str>,
}

pub struct Chunk {
    pub code: Vec<u8>,
    pub lines: Vec<u32>,
    pub constants: Vec<Value>,
}

impl Chunk {
    pub fn new() -> Self {
        Chunk { code: Vec::new(), lines: Vec::new(), constants: Vec::new() }
    }
}

#[repr(C)]
pub struct ObjFunction {
    pub obj: Obj,
    pub arity: usize,
    pub upvalue_count: usize,
    pub chunk: Chunk,
    pub name: *mut ObjString,
}

pub type NativeFn = fn(&[Value]) -> Value;

#[repr(C)]
pub struct ObjNative {
    pub obj: Obj,
    pub function: NativeFn,
}

#[repr(C)]
pub struct ObjClosure {
    pub obj: Obj,
    pub function: *mut ObjFunction,
    pub upvalues: Box<[*mut ObjUpvalue]>,
}

#[repr(C)]
pub struct ObjUpvalue {
    pub obj: Obj,
    pub location: *mut Value,
    pub closed: Value,
    pub next: *mut ObjUpvalue,
}

#[repr(C)]
pub struct ObjClass {
    pub obj: Obj,
    pub name: *mut ObjString,
    pub methods: Table,
    pub initializer: Value,
}

#[repr(C)]
pub struct ObjInstance {
    pub obj: Obj,
    pub class: *mut ObjClass,
    pub fields: Table,
}

#[repr(C)]
pub struct ObjBoundMethod {
    pub obj: Obj,
    pub receiver: Value,
    pub method: *mut ObjClosure,
}

pub fn hash_string(s: &[u8]) -> u32 {
    let mut hash: u32 = 2166136261;
    for &b in s {
        hash ^= b as u32;
        hash = hash.wrapping_mul(16777619);
    }
    hash
}

// ---------------------------------------------------------------------------
// Hash table keyed by interned strings.

#[derive(Clone, Copy)]
pub struct Entry {
    pub key: *mut ObjString,
    pub value: Value,
}

pub struct Table {
    pub count: usize,
    pub entries: Vec<Entry>,
}

const ENTRY_SIZE: usize = std::mem::size_of::<Entry>();

impl Table {
    pub const fn new() -> Self {
        Table { count: 0, entries: Vec::new() }
    }

    pub fn heap_size(&self) -> usize {
        self.entries.len() * ENTRY_SIZE
    }

    #[inline(always)]
    fn find_entry(entries: &[Entry], key: *mut ObjString) -> usize {
        let mask = entries.len() - 1;
        let mut index = unsafe { (*key).hash } as usize & mask;
        let mut tombstone: Option<usize> = None;
        loop {
            let e = unsafe { entries.get_unchecked(index) };
            if e.key.is_null() {
                if e.value.is_nil() {
                    return tombstone.unwrap_or(index);
                } else if tombstone.is_none() {
                    tombstone = Some(index);
                }
            } else if e.key == key {
                return index;
            }
            index = (index + 1) & mask;
        }
    }

    #[inline(always)]
    pub fn get(&self, key: *mut ObjString) -> Option<Value> {
        if self.count == 0 {
            return None;
        }
        let mask = self.entries.len() - 1;
        let mut index = unsafe { (*key).hash } as usize & mask;
        loop {
            let e = unsafe { self.entries.get_unchecked(index) };
            if e.key == key {
                return Some(e.value);
            }
            if e.key.is_null() && e.value.is_nil() {
                return None;
            }
            index = (index + 1) & mask;
        }
    }

    fn adjust_capacity(&mut self, capacity: usize) {
        let mut entries = vec![Entry { key: ptr::null_mut(), value: Value::NIL }; capacity];
        self.count = 0;
        for e in self.entries.iter() {
            if e.key.is_null() {
                continue;
            }
            let i = Table::find_entry(&entries, e.key);
            entries[i] = *e;
            self.count += 1;
        }
        track_free(self.heap_size());
        self.entries = entries;
        track_alloc(self.heap_size());
    }

    /// Returns true if the key was newly added.
    pub fn set(&mut self, key: *mut ObjString, value: Value) -> bool {
        if (self.count + 1) * 4 > self.entries.len() * 3 {
            let cap = if self.entries.len() < 8 { 8 } else { self.entries.len() * 2 };
            self.adjust_capacity(cap);
        }
        let i = Table::find_entry(&self.entries, key);
        let e = &mut self.entries[i];
        let is_new = e.key.is_null();
        if is_new && e.value.is_nil() {
            self.count += 1;
        }
        e.key = key;
        e.value = value;
        is_new
    }

    /// Overwrite an existing key's value; returns false if absent.
    #[inline(always)]
    pub fn set_existing(&mut self, key: *mut ObjString, value: Value) -> bool {
        if self.count == 0 {
            return false;
        }
        let mask = self.entries.len() - 1;
        let mut index = unsafe { (*key).hash } as usize & mask;
        loop {
            let e = unsafe { self.entries.get_unchecked_mut(index) };
            if e.key == key {
                e.value = value;
                return true;
            }
            if e.key.is_null() && e.value.is_nil() {
                return false;
            }
            index = (index + 1) & mask;
        }
    }

    pub fn delete(&mut self, key: *mut ObjString) -> bool {
        if self.count == 0 {
            return false;
        }
        let i = Table::find_entry(&self.entries, key);
        let e = &mut self.entries[i];
        if e.key.is_null() {
            return false;
        }
        e.key = ptr::null_mut();
        e.value = Value::TRUE;
        true
    }

    pub fn add_all(&self, to: &mut Table) {
        for e in self.entries.iter() {
            if !e.key.is_null() {
                to.set(e.key, e.value);
            }
        }
    }

    pub fn find_string(&self, chars: &str, hash: u32) -> *mut ObjString {
        if self.count == 0 {
            return ptr::null_mut();
        }
        let mask = self.entries.len() - 1;
        let mut index = hash as usize & mask;
        loop {
            let e = &self.entries[index];
            if e.key.is_null() {
                if e.value.is_nil() {
                    return ptr::null_mut();
                }
            } else {
                let k = unsafe { &*e.key };
                if k.hash == hash && &*k.chars == chars {
                    return e.key;
                }
            }
            index = (index + 1) & mask;
        }
    }
}

