use crate::compiler;
use crate::object::*;
use crate::value::{Value, format_number};
use std::collections::HashMap;
use std::io::Write;
use std::ptr;

pub mod op {
    pub const CONSTANT: u8 = 0;
    pub const NIL: u8 = 1;
    pub const TRUE: u8 = 2;
    pub const FALSE: u8 = 3;
    pub const POP: u8 = 4;
    pub const GET_LOCAL: u8 = 5;
    pub const SET_LOCAL: u8 = 6;
    pub const GET_GLOBAL: u8 = 7;
    pub const DEFINE_GLOBAL: u8 = 8;
    pub const SET_GLOBAL: u8 = 9;
    pub const GET_UPVALUE: u8 = 10;
    pub const SET_UPVALUE: u8 = 11;
    pub const GET_PROPERTY: u8 = 12;
    pub const SET_PROPERTY: u8 = 13;
    pub const GET_SUPER: u8 = 14;
    pub const EQUAL: u8 = 15;
    pub const GREATER: u8 = 16;
    pub const LESS: u8 = 17;
    pub const ADD: u8 = 18;
    pub const SUBTRACT: u8 = 19;
    pub const MULTIPLY: u8 = 20;
    pub const DIVIDE: u8 = 21;
    pub const NOT: u8 = 22;
    pub const NEGATE: u8 = 23;
    pub const PRINT: u8 = 24;
    pub const JUMP: u8 = 25;
    pub const JUMP_IF_FALSE: u8 = 26;
    pub const LOOP: u8 = 27;
    pub const CALL: u8 = 28;
    pub const INVOKE: u8 = 29;
    pub const SUPER_INVOKE: u8 = 30;
    pub const CLOSURE: u8 = 31;
    pub const CLOSE_UPVALUE: u8 = 32;
    pub const RETURN: u8 = 33;
    pub const CLASS: u8 = 34;
    pub const INHERIT: u8 = 35;
    pub const METHOD: u8 = 36;
}

const FRAMES_MAX: usize = 65536;
const STACK_MAX: usize = FRAMES_MAX * 256;

#[derive(Clone, Copy)]
struct CallFrame {
    closure: *mut ObjClosure,
    ip: *const u8,
    slots: *mut Value,
}

pub enum InterpretResult {
    Ok,
    CompileError,
    RuntimeError,
}

pub struct Vm {
    stack: Vec<Value>,
    stack_top: *mut Value,
    frames: Vec<CallFrame>,
    frame_count: usize,
    globals: Vec<Value>,
    global_names: Vec<*mut ObjString>,
    global_map: HashMap<*mut ObjString, u16>,
    strings: Table,
    init_string: *mut ObjString,
    open_upvalues: *mut ObjUpvalue,
    objects: *mut Obj,
    gray: Vec<*mut Obj>,
    next_gc: usize,
    gc_enabled: bool,
    out: std::io::BufWriter<std::io::Stdout>,
}

fn clock_native(_args: &[Value]) -> Value {
    use std::sync::OnceLock;
    static START: OnceLock<std::time::Instant> = OnceLock::new();
    let start = START.get_or_init(std::time::Instant::now);
    Value::number(start.elapsed().as_secs_f64())
}

impl Vm {
    pub fn new() -> Box<Vm> {
        let mut stack: Vec<Value> = Vec::with_capacity(STACK_MAX);
        // Zeroed allocation; pages are only touched when used.
        unsafe {
            let p = std::alloc::alloc_zeroed(std::alloc::Layout::array::<Value>(STACK_MAX).unwrap());
            stack = Vec::from_raw_parts(p as *mut Value, STACK_MAX, STACK_MAX);
        }
        let mut frames = Vec::with_capacity(FRAMES_MAX);
        frames.resize(
            FRAMES_MAX,
            CallFrame { closure: ptr::null_mut(), ip: ptr::null(), slots: ptr::null_mut() },
        );
        let mut vm = Box::new(Vm {
            stack,
            stack_top: ptr::null_mut(),
            frames,
            frame_count: 0,
            globals: Vec::new(),
            global_names: Vec::new(),
            global_map: HashMap::new(),
            strings: Table::new(),
            init_string: ptr::null_mut(),
            open_upvalues: ptr::null_mut(),
            objects: ptr::null_mut(),
            gray: Vec::new(),
            next_gc: 1024 * 1024,
            gc_enabled: false,
            out: std::io::BufWriter::with_capacity(1 << 16, std::io::stdout()),
        });
        vm.stack_top = vm.stack.as_mut_ptr();
        vm.init_string = vm.intern("init");
        let name = vm.intern("clock");
        let slot = vm.global_slot(name);
        let native = vm.alloc(ObjNative { obj: Vm::header(ObjType::Native), function: clock_native });
        vm.globals[slot as usize] = Value::obj(native);
        clock_native(&[]);
        vm
    }

    pub fn interpret(&mut self, source: &str) -> InterpretResult {
        let Some(function) = compiler::compile(self, source) else {
            return InterpretResult::CompileError;
        };
        self.gc_enabled = true;
        self.push(Value::obj(function));
        let closure = self.new_closure(function);
        self.pop();
        self.push(Value::obj(closure));
        let r = self.call_closure(closure, 0);
        let result = if r { self.run() } else { InterpretResult::RuntimeError };
        let _ = self.out.flush();
        result
    }

    // ---- allocation -----------------------------------------------------

    #[inline(always)]
    fn header(ty: ObjType) -> Obj {
        Obj { ty, marked: false, next: ptr::null_mut() }
    }

    fn alloc<T>(&mut self, obj: T) -> *mut T {
        let size = std::mem::size_of::<T>();
        track_alloc(size);
        if self.gc_enabled && unsafe { BYTES_ALLOCATED } > self.next_gc {
            self.collect_garbage();
        }
        let p = Box::into_raw(Box::new(obj));
        let o = p as *mut Obj;
        unsafe { (*o).next = self.objects };
        self.objects = o;
        p
    }

    pub fn intern(&mut self, s: &str) -> *mut ObjString {
        let hash = hash_string(s.as_bytes());
        let found = self.strings.find_string(s, hash);
        if !found.is_null() {
            return found;
        }
        self.new_string(s.into(), hash)
    }

    fn intern_owned(&mut self, s: String) -> *mut ObjString {
        let hash = hash_string(s.as_bytes());
        let found = self.strings.find_string(&s, hash);
        if !found.is_null() {
            return found;
        }
        self.new_string(s.into_boxed_str(), hash)
    }

    fn new_string(&mut self, chars: Box<str>, hash: u32) -> *mut ObjString {
        track_alloc(chars.len());
        let s = self.alloc(ObjString { obj: Vm::header(ObjType::String), hash, chars });
        self.push(Value::obj(s));
        self.strings.set(s, Value::NIL);
        self.pop();
        s
    }

    pub fn new_function(
        &mut self,
        chunk: Chunk,
        arity: usize,
        upvalue_count: usize,
        name: *mut ObjString,
    ) -> *mut ObjFunction {
        track_alloc(chunk.code.len() * 5 + chunk.constants.len() * 8);
        self.alloc(ObjFunction { obj: Vm::header(ObjType::Function), arity, upvalue_count, chunk, name })
    }

    fn new_closure(&mut self, function: *mut ObjFunction) -> *mut ObjClosure {
        let n = unsafe { (*function).upvalue_count };
        track_alloc(n * 8);
        let upvalues = vec![ptr::null_mut(); n].into_boxed_slice();
        self.alloc(ObjClosure { obj: Vm::header(ObjType::Closure), function, upvalues })
    }

    pub fn global_slot(&mut self, name: *mut ObjString) -> u16 {
        if let Some(&s) = self.global_map.get(&name) {
            return s;
        }
        let s = self.globals.len();
        if s > u16::MAX as usize {
            eprintln!("Too many global variables.");
            std::process::exit(65);
        }
        self.globals.push(Value::UNDEF);
        self.global_names.push(name);
        self.global_map.insert(name, s as u16);
        s as u16
    }

    // ---- stack ----------------------------------------------------------

    #[inline(always)]
    fn push(&mut self, v: Value) {
        unsafe {
            *self.stack_top = v;
            self.stack_top = self.stack_top.add(1);
        }
    }

    #[inline(always)]
    fn pop(&mut self) -> Value {
        unsafe {
            self.stack_top = self.stack_top.sub(1);
            *self.stack_top
        }
    }

    #[inline(always)]
    fn peek(&self, distance: usize) -> Value {
        unsafe { *self.stack_top.sub(1 + distance) }
    }

    // ---- garbage collection --------------------------------------------

    #[inline]
    fn mark_object(&mut self, o: *mut Obj) {
        if o.is_null() {
            return;
        }
        unsafe {
            if (*o).marked {
                return;
            }
            (*o).marked = true;
        }
        self.gray.push(o);
    }

    #[inline]
    fn mark_value(&mut self, v: Value) {
        if v.is_obj() {
            self.mark_object(v.as_obj());
        }
    }

    fn mark_table(&mut self, t: *const Table) {
        unsafe {
            for e in (*t).entries.iter() {
                if !e.key.is_null() {
                    self.mark_object(e.key as *mut Obj);
                    self.mark_value(e.value);
                }
            }
        }
    }

    fn blacken(&mut self, o: *mut Obj) {
        unsafe {
            match (*o).ty {
                ObjType::String | ObjType::Native => {}
                ObjType::Upvalue => {
                    let u = o as *mut ObjUpvalue;
                    self.mark_value((*u).closed);
                }
                ObjType::Function => {
                    let f = o as *mut ObjFunction;
                    self.mark_object((*f).name as *mut Obj);
                    for i in 0..(*f).chunk.constants.len() {
                        let v = (&(*f).chunk.constants)[i];
                        self.mark_value(v);
                    }
                }
                ObjType::Closure => {
                    let c = o as *mut ObjClosure;
                    self.mark_object((*c).function as *mut Obj);
                    for i in 0..(*c).upvalues.len() {
                        let u = (&(*c).upvalues)[i];
                        self.mark_object(u as *mut Obj);
                    }
                }
                ObjType::Class => {
                    let k = o as *mut ObjClass;
                    self.mark_object((*k).name as *mut Obj);
                    self.mark_table(&(*k).methods);
                    self.mark_value((*k).initializer);
                }
                ObjType::Instance => {
                    let i = o as *mut ObjInstance;
                    self.mark_object((*i).class as *mut Obj);
                    self.mark_table(&(*i).fields);
                }
                ObjType::BoundMethod => {
                    let b = o as *mut ObjBoundMethod;
                    self.mark_value((*b).receiver);
                    self.mark_object((*b).method as *mut Obj);
                }
            }
        }
    }

    fn collect_garbage(&mut self) {
        // Roots.
        let mut slot = self.stack.as_mut_ptr();
        while slot < self.stack_top {
            let v = unsafe { *slot };
            self.mark_value(v);
            slot = unsafe { slot.add(1) };
        }
        for i in 0..self.frame_count {
            let c = self.frames[i].closure;
            self.mark_object(c as *mut Obj);
        }
        let mut u = self.open_upvalues;
        while !u.is_null() {
            self.mark_object(u as *mut Obj);
            u = unsafe { (*u).next };
        }
        for i in 0..self.globals.len() {
            let v = self.globals[i];
            self.mark_value(v);
            let n = self.global_names[i];
            self.mark_object(n as *mut Obj);
        }
        self.mark_object(self.init_string as *mut Obj);

        // Trace.
        while let Some(o) = self.gray.pop() {
            self.blacken(o);
        }

        // Weak string table.
        for e in self.strings.entries.iter_mut() {
            if !e.key.is_null() && unsafe { !(*e.key).obj.marked } {
                e.key = ptr::null_mut();
                e.value = Value::TRUE;
            }
        }

        // Sweep.
        let mut prev: *mut Obj = ptr::null_mut();
        let mut obj = self.objects;
        while !obj.is_null() {
            unsafe {
                if (*obj).marked {
                    (*obj).marked = false;
                    prev = obj;
                    obj = (*obj).next;
                } else {
                    let unreached = obj;
                    obj = (*obj).next;
                    if prev.is_null() {
                        self.objects = obj;
                    } else {
                        (*prev).next = obj;
                    }
                    free_object(unreached);
                }
            }
        }

        self.next_gc = unsafe { BYTES_ALLOCATED }.max(1024 * 1024) * 2;
    }

    // ---- runtime helpers -----------------------------------------------

    fn runtime_error(&mut self, msg: &str) {
        let _ = self.out.flush();
        let mut err = String::new();
        err.push_str(msg);
        err.push('\n');
        for i in (0..self.frame_count).rev() {
            let frame = &self.frames[i];
            unsafe {
                let function = (*frame.closure).function;
                let code = (*function).chunk.code.as_ptr();
                let offset = frame.ip.offset_from(code) as usize - 1;
                let line = (&(*function).chunk.lines)[offset];
                err.push_str(&format!("[line {}] in ", line));
                if (*function).name.is_null() {
                    err.push_str("script\n");
                } else {
                    err.push_str(&format!("{}()\n", &*(*(*function).name).chars));
                }
            }
        }
        eprint!("{}", err);
        self.reset_stack();
    }

    fn reset_stack(&mut self) {
        self.stack_top = self.stack.as_mut_ptr();
        self.frame_count = 0;
        self.open_upvalues = ptr::null_mut();
    }

    #[inline(always)]
    fn call_closure(&mut self, closure: *mut ObjClosure, argc: usize) -> bool {
        let arity = unsafe { (*(*closure).function).arity };
        if argc != arity {
            self.runtime_error(&format!("Expected {} arguments but got {}.", arity, argc));
            return false;
        }
        if self.frame_count == FRAMES_MAX {
            self.runtime_error("Stack overflow.");
            return false;
        }
        let frame = &mut self.frames[self.frame_count];
        self.frame_count += 1;
        frame.closure = closure;
        frame.ip = unsafe { (*(*closure).function).chunk.code.as_ptr() };
        frame.slots = unsafe { self.stack_top.sub(argc + 1) };
        true
    }

    fn call_value(&mut self, callee: Value, argc: usize) -> bool {
        if callee.is_obj() {
            let o = callee.as_obj();
            unsafe {
                match (*o).ty {
                    ObjType::BoundMethod => {
                        let b = o as *mut ObjBoundMethod;
                        *self.stack_top.sub(argc + 1) = (*b).receiver;
                        return self.call_closure((*b).method, argc);
                    }
                    ObjType::Class => {
                        let k = o as *mut ObjClass;
                        let inst = self.alloc(ObjInstance {
                            obj: Vm::header(ObjType::Instance),
                            class: k,
                            fields: Table::new(),
                        });
                        *self.stack_top.sub(argc + 1) = Value::obj(inst);
                        let init = (*k).initializer;
                        if !init.is_nil() {
                            return self.call_closure(init.as_obj() as *mut ObjClosure, argc);
                        } else if argc != 0 {
                            self.runtime_error(&format!("Expected 0 arguments but got {}.", argc));
                            return false;
                        }
                        return true;
                    }
                    ObjType::Closure => {
                        return self.call_closure(o as *mut ObjClosure, argc);
                    }
                    ObjType::Native => {
                        let n = o as *mut ObjNative;
                        let args = std::slice::from_raw_parts(self.stack_top.sub(argc), argc);
                        let result = ((*n).function)(args);
                        self.stack_top = self.stack_top.sub(argc + 1);
                        self.push(result);
                        return true;
                    }
                    _ => {}
                }
            }
        }
        self.runtime_error("Can only call functions and classes.");
        false
    }

    fn invoke_from_class(&mut self, class: *mut ObjClass, name: *mut ObjString, argc: usize) -> bool {
        match unsafe { (*class).methods.get(name) } {
            Some(m) => self.call_closure(m.as_obj() as *mut ObjClosure, argc),
            None => {
                self.runtime_error(&format!("Undefined property '{}'.", unsafe { &*(*name).chars }));
                false
            }
        }
    }

    fn invoke(&mut self, name: *mut ObjString, argc: usize) -> bool {
        let receiver = self.peek(argc);
        if !receiver.is_obj_type(ObjType::Instance) {
            self.runtime_error("Only instances have methods.");
            return false;
        }
        let inst = receiver.as_obj() as *mut ObjInstance;
        unsafe {
            if let Some(v) = (*inst).fields.get(name) {
                *self.stack_top.sub(argc + 1) = v;
                return self.call_value(v, argc);
            }
            self.invoke_from_class((*inst).class, name, argc)
        }
    }

    fn bind_method(&mut self, class: *mut ObjClass, name: *mut ObjString) -> bool {
        let method = match unsafe { (*class).methods.get(name) } {
            Some(m) => m,
            None => {
                self.runtime_error(&format!("Undefined property '{}'.", unsafe { &*(*name).chars }));
                return false;
            }
        };
        let receiver = self.peek(0);
        let bound = self.alloc(ObjBoundMethod {
            obj: Vm::header(ObjType::BoundMethod),
            receiver,
            method: method.as_obj() as *mut ObjClosure,
        });
        self.pop();
        self.push(Value::obj(bound));
        true
    }

    fn capture_upvalue(&mut self, local: *mut Value) -> *mut ObjUpvalue {
        let mut prev: *mut ObjUpvalue = ptr::null_mut();
        let mut upvalue = self.open_upvalues;
        unsafe {
            while !upvalue.is_null() && (*upvalue).location > local {
                prev = upvalue;
                upvalue = (*upvalue).next;
            }
            if !upvalue.is_null() && (*upvalue).location == local {
                return upvalue;
            }
        }
        let created = self.alloc(ObjUpvalue {
            obj: Vm::header(ObjType::Upvalue),
            location: local,
            closed: Value::NIL,
            next: upvalue,
        });
        if prev.is_null() {
            self.open_upvalues = created;
        } else {
            unsafe { (*prev).next = created };
        }
        created
    }

    #[inline(always)]
    fn close_upvalues(&mut self, last: *mut Value) {
        unsafe {
            while !self.open_upvalues.is_null() && (*self.open_upvalues).location >= last {
                let u = self.open_upvalues;
                (*u).closed = *(*u).location;
                (*u).location = &mut (*u).closed;
                self.open_upvalues = (*u).next;
            }
        }
    }

    fn print_value(&mut self, v: Value) {
        let s = value_to_string(v);
        let _ = self.out.write_all(s.as_bytes());
        let _ = self.out.write_all(b"\n");
    }

    // ---- interpreter loop ----------------------------------------------

    fn run(&mut self) -> InterpretResult {
        let mut frame: *mut CallFrame = &mut self.frames[self.frame_count - 1];
        let mut ip: *const u8;
        let mut slots: *mut Value;
        let mut constants: *const Value;

        macro_rules! load_frame {
            () => {{
                frame = &mut self.frames[self.frame_count - 1];
                ip = (*frame).ip;
                slots = (*frame).slots;
                constants = (*(*(*frame).closure).function).chunk.constants.as_ptr();
            }};
        }
        macro_rules! save_ip {
            () => {
                (*frame).ip = ip
            };
        }
        macro_rules! read_byte {
            () => {{
                let b = *ip;
                ip = ip.add(1);
                b
            }};
        }
        macro_rules! read_u16 {
            () => {{
                let v = ((*ip as u16) << 8) | (*ip.add(1) as u16);
                ip = ip.add(2);
                v
            }};
        }
        macro_rules! read_constant {
            () => {
                *constants.add(read_byte!() as usize)
            };
        }
        macro_rules! read_string {
            () => {
                read_constant!().as_string()
            };
        }
        macro_rules! push {
            ($v:expr) => {{
                let v = $v;
                *self.stack_top = v;
                self.stack_top = self.stack_top.add(1);
            }};
        }
        macro_rules! pop {
            () => {{
                self.stack_top = self.stack_top.sub(1);
                *self.stack_top
            }};
        }
        macro_rules! peek {
            ($d:expr) => {
                *self.stack_top.sub(1 + $d)
            };
        }
        macro_rules! rt_error {
            ($($arg:tt)*) => {{
                save_ip!();
                self.runtime_error(&format!($($arg)*));
                return InterpretResult::RuntimeError;
            }};
        }
        macro_rules! binary_num {
            ($op:tt, $wrap:expr) => {{
                let b = peek!(0);
                let a = peek!(1);
                if !a.is_number() || !b.is_number() {
                    rt_error!("Operands must be numbers.");
                }
                self.stack_top = self.stack_top.sub(1);
                *self.stack_top.sub(1) = $wrap(a.as_number() $op b.as_number());
            }};
        }

        unsafe {
            ip = (*frame).ip;
            slots = (*frame).slots;
            constants = (*(*(*frame).closure).function).chunk.constants.as_ptr();
            loop {
                let instruction = read_byte!();
                match instruction {
                    op::CONSTANT => {
                        let c = read_constant!();
                        push!(c);
                    }
                    op::NIL => push!(Value::NIL),
                    op::TRUE => push!(Value::TRUE),
                    op::FALSE => push!(Value::FALSE),
                    op::POP => {
                        self.stack_top = self.stack_top.sub(1);
                    }
                    op::GET_LOCAL => {
                        let s = read_byte!() as usize;
                        push!(*slots.add(s));
                    }
                    op::SET_LOCAL => {
                        let s = read_byte!() as usize;
                        *slots.add(s) = peek!(0);
                    }
                    op::GET_GLOBAL => {
                        let s = read_u16!() as usize;
                        let v = *self.globals.get_unchecked(s);
                        if v == Value::UNDEF {
                            let name = &*(*self.global_names[s]).chars;
                            rt_error!("Undefined variable '{}'.", name);
                        }
                        push!(v);
                    }
                    op::DEFINE_GLOBAL => {
                        let s = read_u16!() as usize;
                        *self.globals.get_unchecked_mut(s) = pop!();
                    }
                    op::SET_GLOBAL => {
                        let s = read_u16!() as usize;
                        let g = self.globals.get_unchecked_mut(s);
                        if *g == Value::UNDEF {
                            let name = &*(*self.global_names[s]).chars;
                            rt_error!("Undefined variable '{}'.", name);
                        }
                        *g = peek!(0);
                    }
                    op::GET_UPVALUE => {
                        let s = read_byte!() as usize;
                        let u = *(*(*frame).closure).upvalues.get_unchecked(s);
                        push!(*(*u).location);
                    }
                    op::SET_UPVALUE => {
                        let s = read_byte!() as usize;
                        let u = *(*(*frame).closure).upvalues.get_unchecked(s);
                        *(*u).location = peek!(0);
                    }
                    op::GET_PROPERTY => {
                        let recv = peek!(0);
                        if !recv.is_obj_type(ObjType::Instance) {
                            rt_error!("Only instances have properties.");
                        }
                        let inst = recv.as_obj() as *mut ObjInstance;
                        let name = read_string!();
                        if let Some(v) = (*inst).fields.get(name) {
                            *self.stack_top.sub(1) = v;
                        } else {
                            save_ip!();
                            if !self.bind_method((*inst).class, name) {
                                return InterpretResult::RuntimeError;
                            }
                        }
                    }
                    op::SET_PROPERTY => {
                        let target = peek!(1);
                        if !target.is_obj_type(ObjType::Instance) {
                            rt_error!("Only instances have fields.");
                        }
                        let inst = target.as_obj() as *mut ObjInstance;
                        let name = read_string!();
                        let value = peek!(0);
                        if !(*inst).fields.set_existing(name, value) {
                            (*inst).fields.set(name, value);
                        }
                        self.stack_top = self.stack_top.sub(1);
                        *self.stack_top.sub(1) = value;
                    }
                    op::GET_SUPER => {
                        let name = read_string!();
                        let superclass = pop!().as_obj() as *mut ObjClass;
                        save_ip!();
                        if !self.bind_method(superclass, name) {
                            return InterpretResult::RuntimeError;
                        }
                    }
                    op::EQUAL => {
                        let b = pop!();
                        let a = peek!(0);
                        *self.stack_top.sub(1) = Value::bool(a.equals(b));
                    }
                    op::GREATER => binary_num!(>, Value::bool),
                    op::LESS => binary_num!(<, Value::bool),
                    op::ADD => {
                        let b = peek!(0);
                        let a = peek!(1);
                        if a.is_number() && b.is_number() {
                            self.stack_top = self.stack_top.sub(1);
                            *self.stack_top.sub(1) = Value::number(a.as_number() + b.as_number());
                        } else if a.is_obj_type(ObjType::String) && b.is_obj_type(ObjType::String) {
                            let sa = &*(*a.as_string()).chars;
                            let sb = &*(*b.as_string()).chars;
                            let mut s = String::with_capacity(sa.len() + sb.len());
                            s.push_str(sa);
                            s.push_str(sb);
                            save_ip!();
                            let r = self.intern_owned(s);
                            self.stack_top = self.stack_top.sub(1);
                            *self.stack_top.sub(1) = Value::obj(r);
                        } else {
                            rt_error!("Operands must be two numbers or two strings.");
                        }
                    }
                    op::SUBTRACT => binary_num!(-, Value::number),
                    op::MULTIPLY => binary_num!(*, Value::number),
                    op::DIVIDE => binary_num!(/, Value::number),
                    op::NOT => {
                        let v = peek!(0);
                        *self.stack_top.sub(1) = Value::bool(v.is_falsey());
                    }
                    op::NEGATE => {
                        let v = peek!(0);
                        if !v.is_number() {
                            rt_error!("Operand must be a number.");
                        }
                        *self.stack_top.sub(1) = Value::number(-v.as_number());
                    }
                    op::PRINT => {
                        let v = pop!();
                        self.print_value(v);
                    }
                    op::JUMP => {
                        let off = read_u16!() as usize;
                        ip = ip.add(off);
                    }
                    op::JUMP_IF_FALSE => {
                        let off = read_u16!() as usize;
                        if peek!(0).is_falsey() {
                            ip = ip.add(off);
                        }
                    }
                    op::LOOP => {
                        let off = read_u16!() as usize;
                        ip = ip.sub(off);
                    }
                    op::CALL => {
                        let argc = read_byte!() as usize;
                        save_ip!();
                        let callee = peek!(argc);
                        if !self.call_value(callee, argc) {
                            return InterpretResult::RuntimeError;
                        }
                        load_frame!();
                    }
                    op::INVOKE => {
                        let name = read_string!();
                        let argc = read_byte!() as usize;
                        save_ip!();
                        if !self.invoke(name, argc) {
                            return InterpretResult::RuntimeError;
                        }
                        load_frame!();
                    }
                    op::SUPER_INVOKE => {
                        let name = read_string!();
                        let argc = read_byte!() as usize;
                        let superclass = pop!().as_obj() as *mut ObjClass;
                        save_ip!();
                        if !self.invoke_from_class(superclass, name, argc) {
                            return InterpretResult::RuntimeError;
                        }
                        load_frame!();
                    }
                    op::CLOSURE => {
                        let function = read_constant!().as_obj() as *mut ObjFunction;
                        save_ip!();
                        let closure = self.new_closure(function);
                        push!(Value::obj(closure));
                        let n = (*function).upvalue_count;
                        for i in 0..n {
                            let is_local = read_byte!();
                            let index = read_byte!() as usize;
                            let uv = if is_local != 0 {
                                self.capture_upvalue(slots.add(index))
                            } else {
                                *(*(*frame).closure).upvalues.get_unchecked(index)
                            };
                            *(*closure).upvalues.get_unchecked_mut(i) = uv;
                        }
                    }
                    op::CLOSE_UPVALUE => {
                        self.close_upvalues(self.stack_top.sub(1));
                        self.stack_top = self.stack_top.sub(1);
                    }
                    op::RETURN => {
                        let result = pop!();
                        self.close_upvalues(slots);
                        self.frame_count -= 1;
                        if self.frame_count == 0 {
                            self.stack_top = self.stack_top.sub(1);
                            return InterpretResult::Ok;
                        }
                        self.stack_top = slots;
                        push!(result);
                        load_frame!();
                    }
                    op::CLASS => {
                        let name = read_string!();
                        save_ip!();
                        let k = self.alloc(ObjClass {
                            obj: Vm::header(ObjType::Class),
                            name,
                            methods: Table::new(),
                            initializer: Value::NIL,
                        });
                        push!(Value::obj(k));
                    }
                    op::INHERIT => {
                        let superclass = peek!(1);
                        if !superclass.is_obj_type(ObjType::Class) {
                            rt_error!("Superclass must be a class.");
                        }
                        let sup = superclass.as_obj() as *mut ObjClass;
                        let sub = peek!(0).as_obj() as *mut ObjClass;
                        (*sup).methods.add_all(&mut (*sub).methods);
                        (*sub).initializer = (*sup).initializer;
                        self.stack_top = self.stack_top.sub(1);
                    }
                    op::METHOD => {
                        let name = read_string!();
                        let method = peek!(0);
                        let k = peek!(1).as_obj() as *mut ObjClass;
                        (*k).methods.set(name, method);
                        if name == self.init_string {
                            (*k).initializer = method;
                        }
                        self.stack_top = self.stack_top.sub(1);
                    }
                    _ => std::hint::unreachable_unchecked(),
                }
            }
        }
    }
}

unsafe fn free_object(o: *mut Obj) {
    unsafe {
        let size = match (*o).ty {
            ObjType::String => {
                let p = o as *mut ObjString;
                let n = (*p).chars.len();
                drop(Box::from_raw(p));
                std::mem::size_of::<ObjString>() + n
            }
            ObjType::Function => {
                let p = o as *mut ObjFunction;
                let n = (*p).chunk.code.len() * 5 + (*p).chunk.constants.len() * 8;
                drop(Box::from_raw(p));
                std::mem::size_of::<ObjFunction>() + n
            }
            ObjType::Native => {
                drop(Box::from_raw(o as *mut ObjNative));
                std::mem::size_of::<ObjNative>()
            }
            ObjType::Closure => {
                let p = o as *mut ObjClosure;
                let n = (*p).upvalues.len() * 8;
                drop(Box::from_raw(p));
                std::mem::size_of::<ObjClosure>() + n
            }
            ObjType::Upvalue => {
                drop(Box::from_raw(o as *mut ObjUpvalue));
                std::mem::size_of::<ObjUpvalue>()
            }
            ObjType::Class => {
                let p = o as *mut ObjClass;
                let n = (*p).methods.heap_size();
                drop(Box::from_raw(p));
                std::mem::size_of::<ObjClass>() + n
            }
            ObjType::Instance => {
                let p = o as *mut ObjInstance;
                let n = (*p).fields.heap_size();
                drop(Box::from_raw(p));
                std::mem::size_of::<ObjInstance>() + n
            }
            ObjType::BoundMethod => {
                drop(Box::from_raw(o as *mut ObjBoundMethod));
                std::mem::size_of::<ObjBoundMethod>()
            }
        };
        track_free(size);
    }
}

fn function_name(f: *mut ObjFunction) -> String {
    unsafe {
        if (*f).name.is_null() {
            "<script>".to_string()
        } else {
            format!("<fn {}>", &*(*(*f).name).chars)
        }
    }
}

pub fn value_to_string(v: Value) -> String {
    if v.is_number() {
        return format_number(v.as_number());
    }
    if v == Value::NIL {
        return "nil".into();
    }
    if v == Value::TRUE {
        return "true".into();
    }
    if v == Value::FALSE {
        return "false".into();
    }
    let o = v.as_obj();
    unsafe {
        match (*o).ty {
            ObjType::String => (*(o as *mut ObjString)).chars.to_string(),
            ObjType::Function => function_name(o as *mut ObjFunction),
            ObjType::Native => "<native fn>".into(),
            ObjType::Closure => function_name((*(o as *mut ObjClosure)).function),
            ObjType::Upvalue => "upvalue".into(),
            ObjType::Class => (*(*(o as *mut ObjClass)).name).chars.to_string(),
            ObjType::Instance => {
                format!("{} instance", &*(*(*(*(o as *mut ObjInstance)).class).name).chars)
            }
            ObjType::BoundMethod => function_name((*(*(o as *mut ObjBoundMethod)).method).function),
        }
    }
}

