                        if (*shape).id == ic.shape_id {
                            if ic.slot != NO_SLOT {
                                *sp.sub(1) = *(*inst).fields.get_unchecked(ic.slot as usize);
                            } else {
                                bind!(ic.method);
                            }
                        } else if let Some(slot) = (*shape).find(name) {
                            *ic = InlineCache {
                                shape_id: (*shape).id,
                                slot: slot as u32,
                                next_shape: ptr::null_mut(),
                                method: Value::NIL,
                            };
                            *sp.sub(1) = *(*inst).fields.get_unchecked(slot);
                        } else if let Some(m) = (*(*inst).class).methods.get(name) {
                            *ic = InlineCache {
                                shape_id: (*shape).id,
                                slot: NO_SLOT,
                                next_shape: ptr::null_mut(),
                                method: m,
                            };
                            bind!(m);
                        } else {
                            undefined_property!(name);
                        }
                    }
                    op::SET_PROPERTY => {
                        let target = peek!(1);
                        if !target.is_obj_type(ObjType::Instance) {
                            rt_error!("Only instances have fields.");
                        }
