                        let name = read_string!();
                        let ic = &mut *caches.add(read_u16!() as usize);
                        let value = peek!(0);
                        let shape = (*inst).shape;
                        if (*shape).id == ic.shape_id && ic.next_shape.is_null() {
                            *(*inst).fields.get_unchecked_mut(ic.slot as usize) = value;
                        } else if let Some(slot) = (*shape).find(name) {
                            *ic = InlineCache {
                                shape_id: (*shape).id,
                                slot: slot as u32,
                                next_shape: ptr::null_mut(),
                                method: Value::NIL,
                            };
                            *(*inst).fields.get_unchecked_mut(slot) = value;
                        } else {
                            let next = if (*shape).id == ic.shape_id {
                                ic.next_shape
                            } else {
                                let next = (*shape).transition(name);
                                *ic = InlineCache {
                                    shape_id: (*shape).id,
                                    slot: (*inst).fields.len() as u32,
                                    next_shape: next,
                                    method: Value::NIL,
                                };
