                        let callee = peek!(argc);
                        if callee.is_obj_type(ObjType::Closure) {
                            call_closure!(callee.as_obj() as *mut ObjClosure, argc);
                        } else if callee.is_obj_type(ObjType::Class) {
                            let k = callee.as_obj() as *mut ObjClass;
                            sync!();
