                    op::CLOSE_UPVALUE => {
                        self.close_upvalues(sp.sub(1));
                        sp = sp.sub(1);
                    }
                    op::RETURN => {
                        let result = pop!();
                        if !self.open_upvalues.is_null() {
                            self.close_upvalues(slots);
                        }
