                    *ic = InlineCache {
                        shape_id: (*shape).id,
                        slot: slot as u32,
                        next_shape: ptr::null_mut(),
                        method: Value::NIL,
                    };
                    *(*inst).fields.get_unchecked_mut(slot) = value;
                } else {
                    let next = if (*shape).id == ic.shape_id {
                        ic.next_shape
                    } else {
                        let next = (*shape).transition(name);
                        *ic = InlineCache {
                            shape_id: (*shape).id,
                            slot: (*inst).fields.len() as u32,
                            next_shape: next,
                            method: Value::NIL,
                        };
                        let k = (*inst).class;
                        let n = (*next).names.len();
                        if n > (*k).field_hint {
                            (*k).field_hint = n;
                        }
                        next
                    };
                    let fields = &mut (*inst).fields;
                    let cap = fields.capacity();
                    fields.push(value);
                    if fields.capacity() != cap {
                        track_alloc((fields.capacity() - cap) * 8);
                    }
                    (*inst).shape = next;
                }
                value
            }};
        }
        macro_rules! call_closure {
            ($closure:expr, $argc:expr) => {{
                let closure: *mut ObjClosure = $closure;
                let argc: usize = $argc;
                let function = (*closure).function;
                if argc != (*function).arity {
                    rt_error!("Expected {} arguments but got {}.", (*function).arity, argc);
                }
                if self.frame_count == FRAMES_MAX {
                    rt_error!("Stack overflow.");
                }
                (*frame).ip = ip;
                frame = self.frames.as_mut_ptr().add(self.frame_count);
                self.frame_count += 1;
