        macro_rules! call_value_slow {
            ($callee:expr, $argc:expr) => {{
                sync!();
                if !self.call_value($callee, $argc) {
                    return InterpretResult::RuntimeError;
                }
                sp = self.stack_top;
                tos = *sp.sub(1);
                load_frame!();
