            load_frame!();
            tos = *sp.sub(1);
            loop {
                let instruction = read_byte!();
                match instruction {
                    op::CONSTANT => {
                        let c = read_constant!();
                        push!(c);
                    }
                    op::NIL => push!(Value::NIL),
                    op::TRUE => push!(Value::TRUE),
                    op::FALSE => push!(Value::FALSE),
                    op::POP => drop_n!(1),
                    op::GET_LOCAL => {
                        let s = read_byte!() as usize;
                        push!(*slots.add(s));
