                    op::MULTIPLY_C => binary_const!(*, Value::number),
                    op::DIVIDE_C => binary_const!(/, Value::number),
                    op::LESS_C => binary_const!(<, Value::bool),
                    op::GREATER_C => binary_const!(>, Value::bool),
                    op::EQUAL_C => {
