                    op::EQUAL_C_JIF => {
                        let b = read_constant!();
                        let a = tos;
                        let off = read_u16!() as usize;
                        drop_n!(1);
                        if !a.equals(b) {
                            ip = ip.add(off);
                        }
                    }
