/// `obj.aux`); if they outgrow it they move to a separate heap buffer.
#[repr(C)]
pub struct ObjInstance {
    pub obj: Obj,
    pub class: *mut ObjClass,
    pub shape: *mut Shape,
    pub fields: *mut Value,
    pub len: u32,
    pub cap: u32,
}

impl ObjInstance {
    pub fn layout(inline_cap: usize) -> std::alloc::Layout {
        std::alloc::Layout::from_size_align(
            std::mem::size_of::<ObjInstance>() + inline_cap * std::mem::size_of::<Value>(),
            std::mem::align_of::<ObjInstance>(),
        )
        .unwrap()
    }

    #[inline(always)]
    pub unsafe fn inline_fields(p: *mut ObjInstance) -> *mut Value {
        unsafe { p.add(1) as *mut Value }
    }

    #[inline(always)]
    pub unsafe fn field(&self, slot: usize) -> Value {
        unsafe { *self.fields.add(slot) }
    }

    #[inline(always)]
    pub unsafe fn set_field(&mut self, slot: usize, v: Value) {
        unsafe { *self.fields.add(slot) = v }
    }

    pub unsafe fn push_field(p: *mut ObjInstance, v: Value) {
        unsafe {
            let inst = &mut *p;
            if inst.len == inst.cap {
                let new_cap = (inst.cap as usize * 2).max(4);
                let buf = std::alloc::alloc(std::alloc::Layout::array::<Value>(new_cap).unwrap()) as *mut Value;
                ptr::copy_nonoverlapping(inst.fields, buf, inst.len as usize);
                ObjInstance::free_external(p);
                track_alloc(new_cap * 8);
                inst.fields = buf;
                inst.cap = new_cap as u32;
            }
            *inst.fields.add(inst.len as usize) = v;
            inst.len += 1;
        }
    }

    /// Frees the out-of-line field buffer, if any.
    pub unsafe fn free_external(p: *mut ObjInstance) {
        unsafe {
            let inst = &mut *p;
            if inst.fields != ObjInstance::inline_fields(p) {
                std::alloc::dealloc(
                    inst.fields as *mut u8,
                    std::alloc::Layout::array::<Value>(inst.cap as usize).unwrap(),
                );
                track_free(inst.cap as usize * 8);
            }
        }
    }
}''')
